<?php
require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/functions.php'; $pageTitle='Attendance'; require_role(['teacher']); require_once __DIR__.'/../includes/header.php';$q=$pdo->prepare('SELECT id FROM teachers WHERE user_id=?');$q->execute([user()['id']]);$tid=(int)$q->fetchColumn();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=$_POST['attendance_date'];try{$pdo->beginTransaction();$st=$pdo->prepare("SELECT s.id,s.class_id FROM students s WHERE s.id=? AND s.status='active'");$save=$pdo->prepare("INSERT INTO attendance(student_id,class_id,attendance_date,status,note,recorded_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),note=VALUES(note),recorded_by=VALUES(recorded_by),class_id=VALUES(class_id)");foreach($_POST['status']??[] as $sid=>$status){$st->execute([(int)$sid]);$row=$st->fetch();if(!$row||!user_has_teacher_class($pdo,$tid,(int)$row['class_id']))continue;$save->execute([(int)$sid,$row['class_id'],$date,in_array($status,['present','absent','late','excused'],true)?$status:'present',null,user()['id']]);}$pdo->commit();audit($pdo,'save','attendance',null,$date);flash('success','Attendance saved.');redirect('attendance.php?date='.urlencode($date));}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Attendance could not be saved.';}}
$date=$_GET['date']??date('Y-m-d');$students=$pdo->prepare("SELECT s.id,s.admission_no,s.surname,s.firstname,c.name class_name,c.section FROM students s JOIN classes c ON c.id=s.class_id JOIN teacher_classes tc ON tc.class_id=c.id WHERE tc.teacher_id=? AND s.status='active' ORDER BY c.name,c.section,s.surname");$students->execute([$tid]);$students=$students->fetchAll();$success=flash('success');
?><h2>Attendance</h2><?php if($success): ?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label>Date</label><input class="form-control" type="date" name="attendance_date" value="<?=e($date)?>" required></div><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Class</th><th>Status</th></tr></thead><tbody><?php foreach($students as $s): ?><tr><td><?=e($s['admission_no'].' — '.$s['surname'].' '.$s['firstname'])?></td><td><?=e(trim($s['class_name'].' '.$s['section']))?></td><td><select class="form-select" name="status[<?=$s['id']?>]"><option value="present">Present</option><option value="absent">Absent</option><option value="late">Late</option><option value="excused">Excused</option></select></td></tr><?php endforeach;?></tbody></table></div><button class="btn btn-primary">Save attendance</button></form></div><?php require __DIR__.'/../includes/footer.php';
